       vec3 instancePos = vec3(instanceMatrix[3][0], instanceMatrix[3][1], instanceMatrix[3][2]);

       float dist = distance(instancePos, uMouse);

       // Pass Proximity to Fragment (0.0 = far, 1.0 = close)
       // Range roughly 0 to 30
       vProximity = 1.0 - clamp(dist / 30.0, 0.0, 1.0);

       // Zones
       float rPush = 10.0; // Close range: Repel
       float rPull = 30.0; // Mid range: Attract

       vec3 worldOffset = vec3(0.0);

       if (dist < rPush) {
         // --- PUSH (Repulsion) ---
         vec3 dir = normalize(instancePos - uMouse);
         float f = (rPush - dist) / rPush; 
         f = f * f; // Quadratic ramp up
         worldOffset = dir * f * 12.0;

       } else if (dist < rPull) {
         // --- PULL (Attraction) ---
         // We want to gently pull them in if they are wandering nearby
         vec3 dir = normalize(uMouse - instancePos);

         // Normalize distance within the pull band (0.0 at rPush, 1.0 at rPull)
         float range = rPull - rPush;
         float normDist = (dist - rPush) / range;

         // Use a sine hump to fade attraction in and out smoothly
         // Starts at 0, peaks in middle, ends at 0
         float f = sin(normDist * 3.14159);

         worldOffset = dir * f * 5.0; 
       }

       // Transform World Offset to Local Space
       // Vector * Matrix = multiply by Transpose (Inverse Rotation)
       vec3 localOffset = worldOffset * mat3(instanceMatrix);

       transformed += localOffset;

       vHue = instanceHue;
       vBand = instanceBand;
      `
    );

    // 4. Inject Fragment Shader Global Variables & Functions
    const fsGlobal = `
      varying float vHue;
      varying float vBand;
      varying float vProximity;
      uniform float uBands;
      uniform float uJitter;
      uniform float uTime;
      uniform float uSpeed;
      uniform int uPalette;

      vec3 hsv2rgb(vec3 c){
        vec4 K = vec4(1.0, 2.0/3.0, 1.0/3.0, 3.0);
        vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
        return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
      }

      vec3 paletteColor(int idx, float t){
        if(idx==0){ // natural blues
          return mix(vec3(0.1,0.4,0.9), vec3(0.0,1.0,0.8), t); 
        } else if(idx==1){ // neon
          return mix(vec3(0.1,0.9,1.0), vec3(1.0,0.1,0.8), t); 
        } else if(idx==2){ // sunset
          return mix(vec3(1.0,0.3,0.1), vec3(0.6,0.0,0.5), t); 
        } else if(idx==3){ // cyber (green/yellow)
          return mix(vec3(0.0, 0.3, 0.0), vec3(0.4, 1.0, 0.1), t);
        } else if(idx==4){ // cherry (red/pink/white)
          return mix(vec3(0.8, 0.0, 0.2), vec3(1.0, 0.8, 0.9), t);
        } else if(idx==5){ // spectral (rainbow)
          vec3 hsv = vec3(t, 0.8, 1.0);
          return hsv2rgb(hsv);
        } else if(idx==6){ // plasma (purple/cyan/electric)
          return mix(vec3(0.5, 0.0, 1.0), vec3(0.0, 1.0, 1.0), t);
        } else if(idx==7){ // golden (amber/gold)
          return mix(vec3(1.0, 0.5, 0.0), vec3(1.0, 0.9, 0.4), t);
        } else { // frozen (deep blue/white)
          return mix(vec3(0.0, 0.2, 0.6), vec3(0.8, 0.95, 1.0), t);
        }
      }
    `;
    shader.fragmentShader = fsGlobal + shader.fragmentShader;

    // 5. Inject Fragment Logic (Color Mixing + Emissive Glow)
    shader.fragmentShader = shader.fragmentShader.replace(
      '#include <color_fragment>',
      `#include <color_fragment>
       // Per-instance palette mix: banded groups + jittered hue shift
       float bandIdx = floor(vBand * uBands + 1e-5);
       float t = (uBands <= 1.0) ? 0.5 : bandIdx / max(1.0, uBands - 1.0);

       vec3 paletteCol = paletteColor(uPalette, t);

       // Add some iridescent jitter
       float hShift = (vHue - 0.5) * 0.5 * uJitter; 

       // Interaction Shift: If close to mouse, shift hue slightly
       hShift += vProximity * 0.2;

       vec3 jitterCol = hsv2rgb(vec3(fract(0.6 + hShift), 0.8, 1.0));

       vec3 finalCol = mix(paletteCol, jitterCol, uJitter);

       // Multiply by vertex color (AO from Voxel) if available
       #ifdef USE_COLOR
         finalCol *= vColor.rgb;
       #endif

       diffuseColor.rgb = finalCol;

       // --- Dynamic Emissive ---
       // Pulse based on Time and Speed
       // Faster speed = faster pulse
       float pulseFreq = 2.0 * uSpeed;
       float pulse = 1.0 + 0.3 * sin(uTime * pulseFreq + vHue * 10.0);

       // Proximity Boost: Glow brighter when near interaction
       float proximityGlow = 1.0 + vProximity * 2.0;

       // Standard multiplier for r150 lighting
       totalEmissiveRadiance = finalCol * 1.5 * pulse * proximityGlow; 
      `
    );

    mat.userData.shader = shader;
  };

  return mat;
}

import React, { useState, useEffect, Suspense } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, Stars, Sparkles } from '@react-three/drei';
import { EffectComposer, Bloom, Vignette, Noise, ChromaticAberration, Scanline } from '@react-three/postprocessing';
import { XR, VRButton, Controllers, Hands } from '@react-three/xr';
import { useXR } from '@react-three/xr';
import FishSchool from './components/FishSchool';
import ControlPanel from './components/ControlPanel';
import SpatialUI from './components/SpatialUI';
import AnaglyphRenderer from './components/AnaglyphRenderer';
import { DEFAULT_PARAMS, PRESETS } from './constants';
import { SimulationParams, AnimationMode } from './types';
import * as THREE from 'three';

// Separate component to handle Logic inside Canvas that needs useXR
const SceneContent: React.FC<{
    params: SimulationParams,
    handleParamChange: (p: Partial<SimulationParams>) => void,
    handlePreset: (n: string) => void
}> = ({ params, handleParamChange, handlePreset }) => {
    const { isPresent } = useXR();

    return (
        <>
            <color attach="background" args={['#05070a']} />
            <fog attach="fog" args={['#05070a', 10, 60]} />

            {/* Ambient Environment */}
            <Stars radius={100} depth={50} count={3000} factor={4} saturation={0} fade speed={1} />

            {/* Marine Snow / Drifting Particulates */}
            <Sparkles 
                count={150}
                scale={25}
                size={4}
                speed={0.4}
                opacity={0.2}
                noise={0.2}
                color="#ccf0ff" 
            />

            {/* Lighting - Physical intensities for Three.js r160 */}
            <ambientLight intensity={2.0} color="#001133" />

            <spotLight 
                position={[10, 20, 10]} 
                intensity={3000} 
                penumbra={1} 
                color="#ccf0ff" 
                decay={1.5}
                distance={100}
            />
            <pointLight 
                position={[-10, -10, -10]} 
                intensity={1500} 
                color="#0044ff" 
                decay={1.5}
                distance={100}
            />

            {/* XR Inputs */}
            <Controllers />
            <Hands />

            {/* Main Simulation */}
            <Suspense fallback={null}>
                <FishSchool params={params} />
            </Suspense>

            {/* Spatial UI (Only visible in VR) */}
            {isPresent && (
                <SpatialUI 
                    params={params} 
                    onChange={handleParamChange} 
                    onPreset={handlePreset} 
                />
            )}

            {/* 
                RENDER PIPELINE 
                1. Stereo Mode (Red/Cyan Glasses) - Desktop Only
                2. XR Mode (Headset) - No PostProcessing (Performance)
                3. Desktop Standard - Full PostProcessing
            */}
            {params.stereo && !isPresent ? (
                <AnaglyphRenderer />
            ) : (
                !isPresent && (
                    <EffectComposer disableNormalPass>
                        <Bloom 
                            luminanceThreshold={0.2} 
                            mipmapBlur 
                            intensity={1.2} 
                            radius={0.5} 
                        />
                        <Noise opacity={0.02} />
                        <Vignette eskil={false} offset={0.1} darkness={1.1} />

                        {params.hologram && (
                            <>
                                <ChromaticAberration 
                                    offset={new THREE.Vector2(0.005, 0.005)} 
                                    radialModulation={false} 
                                    modulationOffset={0} 
                                />
                                <Scanline 
                                    density={1.25} 
                                    scrollSpeed={0.02} 
                                    opacity={0.2} 
                                />
                            </>
                        )}
                    </EffectComposer>
                )
            )}

            {/* Camera Controls - Only for Desktop */}
            {!isPresent && (
                <OrbitControls 
                    target={[0, 1, 0]} 
                    enablePan={false} 
                    enableDamping 
                    dampingFactor={0.05}
                    autoRotate={false}
                    rotateSpeed={0.5}
                />
            )}
        </>
    );
};

const App: React.FC = () => {
  const [params, setParams] = useState<SimulationParams>(DEFAULT_PARAMS);

  // Handle params update
  const handleParamChange = (newParams: Partial<SimulationParams>) => {
    setParams((prev) => ({ ...prev, ...newParams }));
  };

  // Handle Presets
  const handlePreset = (name: string) => {
    const p = PRESETS[name];
    if (p) {
      handleParamChange(p);
    }
  };

  // Keyboard Shortcuts
  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      const k = e.key.toLowerCase();
      if (k >= '1' && k <= '9') {
        handleParamChange({ mode: parseInt(k, 10) as AnimationMode });
      }
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, []);

  return (
    <>
        {/* Enter VR Button (Overlay) */}
        <VRButton className="absolute bottom-8 left-1/2 -translate-x-1/2 z-50 bg-white/10 hover:bg-sky-500 text-white font-bold py-2 px-6 rounded-full backdrop-blur-md border border-white/20 transition-all" />

        <div className="relative w-full h-screen bg-black overflow-hidden select-none">

        {/* Desktop UI Overlay */}
        <ControlPanel 
            params={params} 
            onChange={handleParamChange} 
            onPreset={handlePreset} 
        />

        <Canvas
            camera={{ position: [0, 6, 22], fov: 55 }}
            dpr={[1, 1.5]} 
            gl={{ 
            antialias: true, 
            stencil: false, 
            depth: true,
            preserveDrawingBuffer: true // Required for reliable canvas recording fallback
            }} 
        >
            <XR>
                <SceneContent 
                    params={params}
                    handleParamChange={handleParamChange}
                    handlePreset={handlePreset}
                />
            </XR>
        </Canvas>
        </div>
    </>
  );
};

export default App;

